                                                "END_DATE" CHARACTER VARYING(255),
                                                "GUID" CHARACTER VARYING(255),
                                                "INTERNAL_NUMBER" CHARACTER VARYING(255),
                                                "CREATE_DATE" CHARACTER VARYING(255),
                                                "MRPA_XML_FILENAME" CHARACTER VARYING(255),
                                                "ORGANISATION_ID" BIGINT,
                                                "PRINCIPAL_ID" BIGINT,
                                                "RECALLED_XML_PATH" CHARACTER VARYING,
                                                "REPRESENTATIVE_ID" BIGINT,
                                                "SIG_PATH" CHARACTER VARYING,
                                                "START_DATE" CHARACTER VARYING(255),
                                                "MRPA_RECALL_ID" BIGINT
);
ALTER TABLE "PUBLIC"."MRPA_REGISTRY" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_CD" PRIMARY KEY("ID");
